float f_n_rand(float n){
    n = fract(n * .1031);
    n *= n + 33.33;
    n *= n + n;
    return fract(n);
}
vec2 f_o_idx(vec2 o_trn, vec2 o_scl){
    //calculate an index based on a o_trn translation and o_scl scale
    float n_idx_flr = floor(o_trn.x)
        + floor(o_trn.y) * floor(o_scl.x);
    return vec2(
        n_idx_flr, 
        n_idx_flr / (floor(o_scl.x)*floor(o_scl.y))
    );
}
vec2 f_o_radial(vec2 o_fc_nor_off, float n_its, float n_it){
    float n_rand = f_n_rand(n_it);//*sin(iTime)*0.01;
    float n_tau = 6.283185;
    float n_one_it_nor = 1./n_its;
    float n_it_nor = n_it/ n_its;
    float n_dcntr = length(o_fc_nor_off);

    float n_ang_off = sin(n_dcntr*12.+iTime*4.)*n_one_it_nor*n_rand*5.;
    n_ang_off = n_one_it_nor*0.5;
    //n_ang_off = (sin(iTime+n_dcntr*20.)*0.5+0.5)*n_one_it_nor;
    //n_ang_off = 0.;
    vec2 o = vec2(
        cos(((n_it/ n_its)+n_ang_off) * n_tau) * n_dcntr,
        sin(((n_it/ n_its)+n_ang_off) * n_tau) * n_dcntr
    );
    float n_len = length(o_fc_nor_off - o);
    float n_len_nor = n_len/n_dcntr*n_its/4.;// i dont know if this is correct, probably not...
    //n_len_nor = smoothstep(0.1, 0.11, n_len_nor);
    return vec2(n_len, n_len_nor);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float n_dscl = 1.;// dscl down scale
    vec2 o_lires = iResolution.xy * n_dscl;// lres low resolution
    vec2 o_lfc = fragCoord.xy * n_dscl;
    float n_t = iTime*0.5; 


    float n_ratio_1to_iresx = 1./ o_lires.x;

    vec2 o_lfc_nor = floor(o_lfc) / o_lires; // low frag coord normalized
    vec2 o_lfc_nor_off = (floor(o_lfc)-0.5*o_lires.xy)/ o_lires.y;
    vec2 o_fc_nor = fragCoord.xy / iResolution.xy;
    vec2 o_fc_nor_off = (fragCoord.xy-0.5*iResolution.xy) / iResolution.y;
    vec2 o_mo_nor_off = (iMouse.xy-0.5*iResolution.xy) / iResolution.y;

    //o_fc_nor_off *= 2.;
    float n_its = (sin(iTime)*.5+0.5)*18.+2.;
    float n_tau = 6.283185;

    float n_ang_nor = fract(atan(o_fc_nor_off.y, o_fc_nor_off.x)/n_tau);

    float n_dcntr = length(o_fc_nor_off);

    float n_one_it_nor = 1./n_its;
    float n_it = floor(n_ang_nor/n_one_it_nor);
    float n_it_nor = n_it / n_its;
    float n_nei = floor((1.-n_dcntr)*n_its);
    vec2 o_len_min = vec2(1.);
    float n_it_min = 0.;


    for(float n = 0.; n < n_nei ; n+=1.){
        float n_pm = n - floor(n_nei/2.);
        float n_it_new = mod(n_it+n_pm, n_its);
        vec2 o_len = f_o_radial(o_fc_nor_off, n_its, n_it_new);
        if(o_len.x < o_len_min.x){
            o_len_min = o_len;
            n_it_min = n_it_new;
        }
    }

    if(iMouse.z == 0.){
        o_mo_nor_off = vec2(sin(n_t), cos(n_t)*0.5+0.5);
    }

    fragColor = vec4(o_len_min.y);

    if(o_fc_nor_off.x > o_mo_nor_off.x){
        fragColor = vec4(o_len_min.x);
    }




}
